def scaled_attention(query, keys):
    scale = query.shape[-1] ** -0.5
    logits = torch.einsum('bd,bnd->bn', query, keys) * scale
    return torch.softmax(logits, dim=-1)

def centered_prior(K, eps=1e-8):
    K = K.float()
    if not torch.isfinite(K).all():
        raise ValueError("non-finite K")
    std = K.std(unbiased=False)
    if std < eps:
        return torch.zeros_like(K)  # uniform sanity：常数先验贡献必须为零
    return (K - K.mean()) / std

